"Mahfudzot 2": {
        "1": {
            judul: "أركان الإيمان",
            subbab: [
                "يا أيها الذين آمنوا آمنوا بالله .... (النساء: ١٣٦)",
                "إنا كل شيء خلقناه بقدر (القمر: ٤٩)",
                "ما أصاب من مصيبة في الأرض... (الحديد: ٢٢)"
            ]
        },
        2: {
            judul: "أركان الإسلام",
            subbab: [
                "شهد الله أنه لا إله إلا هو .... (آل عمران: ١٨)",
                "ما كان محمد أبا أحد ... (الأحزاب: ٤٠)",
                "وأقيموا الصلاة وآتوا الزكاة.. (البقرة: ٤٣)",
                "يا أيها الذين آمنوا كتب... (البقرة: ١٨٣)",
                "ولله على الناس حج البيت... (آل عمران: ٩٧)"
            ]
        },
        3: {
            judul: "الصلاة",
            subbab: [
                "وما أمروا إلا ليعبدوا ... (البينة: ٥)",
                "أيها المدثر... (المدثر: ١-٤)",
                "يا أيها الذين آمنوا إذا قمتم... (المائدة: ٦)",
                "يا أيها الذين آمنوا لا تقربوا الصلاة... (النساء: ٤٣)",
                "إنما حرم عليكم الميتة... (البقرة: ١٧٣)",
                "يا أيها النبي قل لأزواجك ... (الأحزاب: ٥٩)",
                "فاصبر على ما يقولون... (طه: ١٣٠)",
                "أقم الصلاة لدلوك الشمس... (الإسراء: ٧٨)",
                "قد نرى تقلب وجهك... (البقرة: ١٤٤)",
                "وإذا كنت فيهم فأقمت.. (النساء: ١٠٢)",
                "يا أيها الذين آمنوا إذا نودي للصلاة.... (الجمعة ٩)",
                "وما أرسلنا من رسول إلا.... (إبراهيم: ٤)",
                "وإذا رأوا تجارة.... (الجمعة: ١١)",
                "ومن الليل فتهجد... (الإسراء ٧٩)",
                "أولئك الذين أنعم الله... (مريم: ٥٨)",
                "إنا أعطيناك الكوثر... (الكوثر: ١-٣)",
                "شهر رمضان الذي.... (البقرة: ١٨٥)",
                "واذكرو الله في أيام..... (البقرة ٢٠٣)",
                "ومن آياته الليل .... (فصلت: ٣٧)",
                "ولا تصل على أحد منهم.... (التوبة: ٨٤)",
                "فبعث الله غرابا.... (المائدة: ٣١)"
            ]
        },
        4: {
            judul: "الزكاة",
            subbab: [
                "وأقيموا الصلاة وآتوا الزكاة.... (البقرة: ٤٣)",
                "لا يحسبين الذين يبخلون... (آل عمران: ١٨٠)",
                "وهو الذي أنشأ جنات... (الأنعام: ١٤١)",
                "يا أيها الذين آمنوا إن كثيرا.... (التوبة: ٣٤-٣٥)",
                "يأيها الذين آمنوا أنفقوا .... (البقرة ٢٦٧)",
                "إنما الصدقات للفقراء.... (التوبة: ٦٠)"
            ]
        },
        5: {
            judul: "الصوم",
            subbab: [
                "يا أيها الذين آمنوا كتب... (البقرة: ١٨٣)",
                "شهر رمضان الذي... (البقرة: ١٨٥)",
                "أحل لكم ليلة الصيام... (البقرة: ١٨٧)",
                "أياما معدودات فمن كان منكم.... (البقرة: ١٨٤)",
                "هو الذي جعل الشمس ضياء.... (يونس: ٥)",
                "أحل لكم ليلة الصيام الرفث.... (البقرة: ١٨٧)",
                "إنا أنزلنا في ليلة القدر.... (القدر ١-٥)"
            ]
        },
  "6": {
    "judul": "الحج",
    "subbab": [
      "٤٣. ولله على الناس... (آل عمران: ٩٧)",
      "٤٤. ثم ليقضوا تفثهم.... (الحج: ٢٩)",
      "٤٥. إن الصفا والمروة.... (البقرة: ١٥٨)",
      "٤٦. الحج أشهر معلومات.... (البقرة: ١٩٧)",
      "٤٧. واذكروا الله في.... (البقرة: ٢٠٣)",
      "٤٨. فإذا أمنتم فمن... (البقرة: ١٩٦)",
      "إنا أعطيناك الكوثر.... (الكوثر: ١-٣)"
    ]
  }
},
