// FUNGSI NAVIGASI MENU GURU (GANTI VIEW) - DIREVISI
// ==================================================================
function bukaMenuGuru(jenisView) {
    document.getElementById('guru-menu-utama').style.display = 'none';
    document.getElementById('view-data-guru').style.display = 'none';
    document.getElementById('view-target-siswa').style.display = 'none';

    const viewAktifitas = document.getElementById('view-aktifitas-guru');
    if (viewAktifitas) viewAktifitas.style.display = 'none';

    if (jenisView === 'data') {
        document.getElementById('view-data-guru').style.display = 'block';
        if (typeof renderTabelGuru === 'function') renderTabelGuru();
    } else if (jenisView === 'target') {
        document.getElementById('view-target-siswa').style.display = 'block';
    } else if (jenisView === 'aktifitas') {
        document.getElementById('view-aktifitas-guru').style.display = 'block';
        if (typeof renderAktifitasGuruLengkap === 'function') renderAktifitasGuruLengkap();
    }
}

    function kembaliKeMenuGuru() {
        document.getElementById('guru-menu-utama').style.display = 'block';

        document.getElementById('view-data-guru').style.display = 'none';
        document.getElementById('view-target-siswa').style.display = 'none';

        const viewAktifitas = document.getElementById('view-aktifitas-guru');
        if (viewAktifitas) viewAktifitas.style.display = 'none';
    }

    // ==================================================================
// MANAJEMEN DATA GURU & HAK AKSES (GLOBAL SCOPE)
// Diletakkan di luar document.addEventListener agar tombol HTML bisa memanggilnya
// ==================================================================

function renderTabelGuru() {
    const tbody = document.getElementById('tabel-body-guru');
    if (!tbody) return;

    const searchInput = document.getElementById("search-guru");
    const ddlTahun = document.getElementById("filter-tahun-guru");
    const ddlDaerah = document.getElementById("filter-daerah-guru");
    const ddlBagian = document.getElementById("filter-bagian-guru");

    const searchVal = searchInput ? searchInput.value.toLowerCase() : "";
    const filterTahun = ddlTahun && ddlTahun.value ? ddlTahun.value : "Semua";
    const filterDaerah = ddlDaerah && ddlDaerah.value ? ddlDaerah.value : "Semua";
    const filterBagian = ddlBagian && ddlBagian.value ? ddlBagian.value : "Semua";

    let setTahun = new Set();
    let setDaerah = new Set();
    let setBagian = new Set();
    let count = 0;
    let barisHTML = "";

    daftarGuru.forEach((guru, index) => {
        if (guru.tahun && guru.tahun !== "-") setTahun.add(guru.tahun);
        if (guru.daerah && guru.daerah !== "-") setDaerah.add(guru.daerah);
        if (guru.bagian && guru.bagian !== "-") setBagian.add(guru.bagian);

        const matchSearch = (guru.noGuru && guru.noGuru.toLowerCase().includes(searchVal)) || (guru.nama && guru.nama.toLowerCase().includes(searchVal));
        const matchTahun = (filterTahun === "Semua" || guru.tahun === filterTahun);
        const matchDaerah = (filterDaerah === "Semua" || guru.daerah === filterDaerah);
        const matchBagian = (filterBagian === "Semua" || guru.bagian === filterBagian);

        if (matchSearch && matchTahun && matchDaerah && matchBagian) {
            count++;
            barisHTML += `
            <tr style="border-bottom: 1px solid #eee;">
                <td style="padding: 10px; border: 1px solid #eee; font-weight: bold; color: #b5532a;">${guru.noGuru || '-'}</td>
                <td style="padding: 10px; border: 1px solid #eee; font-weight: bold; color: #3a2f2a;">${guru.nama}</td>
                <td style="padding: 10px; border: 1px solid #eee;">${guru.tahun || '-'}</td>
                <td style="padding: 10px; border: 1px solid #eee;">${guru.daerah || '-'}</td>
                <td style="padding: 10px; border: 1px solid #eee;"><span style="background: #faf5ec; color: #b5532a; padding: 3px 8px; border-radius: 10px; font-size: 12px; font-weight: bold; border: 1px solid #f2e7da;">${guru.bagian || '-'}</span></td>
                <td style="padding: 10px; border: 1px solid #eee;">${guru.noHp || '-'}</td>
                <td style="padding: 10px; border: 1px solid #eee; text-align: center;">
                    <button onclick="bukaModalEditGuru(${index})" style="background: #f39c12; color: white; border: none; padding: 5px 10px; border-radius: 4px; cursor: pointer; font-size: 12px; margin-bottom: 2px;" title="Edit"><i class="fas fa-edit"></i></button>
                    <button onclick="hapusGuru(${index})" style="background: #c0392b; color: white; border: none; padding: 5px 10px; border-radius: 4px; cursor: pointer; font-size: 12px; margin-left: 5px;" title="Hapus"><i class="fas fa-trash"></i></button>
                </td>
            </tr>
            `;
        }
    });

    if (count === 0) {
        barisHTML = `<tr><td colspan="7" style="text-align: center; padding: 15px; color: #777; font-style: italic;">Tidak ada data guru yang cocok.</td></tr>`;
    }

    tbody.innerHTML = barisHTML;
    updateDropdownFilterGuru(setTahun, setDaerah, setBagian);
}

function updateDropdownFilterGuru(setTahun, setDaerah, setBagian) {
    const ddlTahun = document.getElementById("filter-tahun-guru");
    const ddlDaerah = document.getElementById("filter-daerah-guru");
    const ddlBagian = document.getElementById("filter-bagian-guru");

    if (ddlTahun) {
        const currentTahun = ddlTahun.value;
        ddlTahun.innerHTML = `<option value="Semua">Semua Tahun</option>`;
        [...setTahun].sort((a, b) => b - a).forEach(t => ddlTahun.innerHTML += `<option value="${t}">${t}</option>`);
        ddlTahun.value = currentTahun || "Semua";
    }

    if (ddlDaerah) {
        const currentDaerah = ddlDaerah.value;
        ddlDaerah.innerHTML = `<option value="Semua">Semua Daerah</option>`;
        [...setDaerah].sort().forEach(d => ddlDaerah.innerHTML += `<option value="${d}">${d}</option>`);
        ddlDaerah.value = currentDaerah || "Semua";
    }

    if (ddlBagian) {
        const currentBagian = ddlBagian.value;
        ddlBagian.innerHTML = `<option value="Semua">Semua Bagian</option>`;
        [...setBagian].sort().forEach(b => ddlBagian.innerHTML += `<option value="${b}">${b}</option>`);
        ddlBagian.value = currentBagian || "Semua";
    }
}

function resetFilterGuru() {
    if (document.getElementById("search-guru")) document.getElementById("search-guru").value = "";
    if (document.getElementById("filter-tahun-guru")) document.getElementById("filter-tahun-guru").value = "Semua";
    if (document.getElementById("filter-daerah-guru")) document.getElementById("filter-daerah-guru").value = "Semua";
    if (document.getElementById("filter-bagian-guru")) document.getElementById("filter-bagian-guru").value = "Semua";
    renderTabelGuru();
}

function simpanGuruKeStorage() {
    localStorage.setItem('daftarGuru', JSON.stringify(daftarGuru));
    if (typeof firebaseDb !== 'undefined') {
        firebaseDb.ref('daftarGuru').set(daftarGuru).catch(err => console.error("Gagal sinkron guru ke Firebase:", err));
    }
}

function bukaModalGuru() {
    document.getElementById('modal-guru-judul').textContent = "Tambah Data Guru";
    document.getElementById('edit-index-guru').value = "";

    document.getElementById('input-noguru-guru').value = "";
    document.getElementById('input-nama-guru').value = "";
    document.getElementById('input-tahun-guru').value = "";
    document.getElementById('input-daerah-guru').value = "";
    document.getElementById('input-bagian-guru').value = "";
    document.getElementById('input-hp-guru').value = "";    { const _kw = document.getElementById('input-kelaswali-guru'); if (_kw) _kw.value = ("") || ""; }

    document.getElementById('modal-guru').style.display = 'flex';
}

function bukaModalEditGuru(index) {
    const guru = daftarGuru[index];
    if (!guru) return;

    document.getElementById('modal-guru-judul').textContent = "Edit Data Guru";
    document.getElementById('edit-index-guru').value = index;

    document.getElementById('input-noguru-guru').value = guru.noGuru || "";
    document.getElementById('input-nama-guru').value = guru.nama || "";
    document.getElementById('input-tahun-guru').value = guru.tahun || "";
    document.getElementById('input-daerah-guru').value = guru.daerah || "";
    document.getElementById('input-bagian-guru').value = guru.bagian || "";
    document.getElementById('input-hp-guru').value = guru.noHp || "";    { const _kw = document.getElementById('input-kelaswali-guru'); if (_kw) _kw.value = (guru.kelasWali || "") || ""; }

    document.getElementById('modal-guru').style.display = 'flex';
}

function tutupModalGuru() {
    document.getElementById('modal-guru').style.display = 'none';
}

function simpanDataGuru() {
    const noGuru = document.getElementById('input-noguru-guru').value.trim() || ("G-" + Date.now().toString().slice(-4));
    const nama = document.getElementById('input-nama-guru').value.trim();
    const tahun = document.getElementById('input-tahun-guru').value.trim() || "-";
    const daerah = document.getElementById('input-daerah-guru').value.trim() || "-";
    const bagian = document.getElementById('input-bagian-guru').value.trim() || "-";
    const noHp = document.getElementById('input-hp-guru').value.trim() || "-";
    const kelasWali = (document.getElementById('input-kelaswali-guru')?.value || '').trim();
    const editIndex = document.getElementById('edit-index-guru').value;

    if (!nama) {
        alert("Nama Guru wajib diisi!");
        return;
    }

    if (typeof verifikasiPasswordAdmin === 'function' && !verifikasiPasswordAdmin(editIndex === "" ? "menambah data guru" : "mengubah data guru")) return;

    if (editIndex === "") {
        daftarGuru.push({ noGuru, nama, tahun, daerah, bagian, noHp, kelasWali });
        if (typeof catatAktivitasGuru === 'function') catatAktivitasGuru(`Menambahkan data guru baru: ${nama}`);
    } else {
        daftarGuru[editIndex] = { noGuru, nama, tahun, daerah, bagian, noHp, kelasWali };
        if (typeof catatAktivitasGuru === 'function') catatAktivitasGuru(`Mengubah data guru: ${nama}`);
    }

    simpanGuruKeStorage();
    tutupModalGuru();
    renderTabelGuru();
    alert("Data guru berhasil disimpan!");
}

function hapusGuru(index) {
    if (typeof verifikasiPasswordAdmin === 'function' && !verifikasiPasswordAdmin("menghapus data guru")) return;

    if (confirm(`Yakin ingin menghapus guru ${daftarGuru[index].nama}?`)) {
        daftarGuru.splice(index, 1);
        simpanGuruKeStorage();
        renderTabelGuru();
        alert("Data guru berhasil dihapus.");
    }
}

// ==================================================================
// FUNGSI EXPORT & IMPORT EXCEL GURU (FINAL & GLOBAL)
// ==================================================================

function exportExcelGuru() {
    if (typeof daftarGuru === 'undefined' || daftarGuru.length === 0) {
        alert("Tidak ada data guru untuk diexport!");
        return;
    }

    if (typeof XLSX === 'undefined') {
        alert("Sistem gagal memuat Excel. Pastikan script SheetJS sudah terpasang di HTML!");
        return;
    }

    const dataExcel = daftarGuru.map((guru, index) => ({
        "No": index + 1,
        "No Guru / ID": guru.noGuru || "-",
        "Nama Guru": guru.nama || "-",
        "Tahun": guru.tahun || "-",
        "Daerah": guru.daerah || "-",
        "Bagian": guru.bagian || "-",
        "No HP": guru.noHp || "-"
    }));

    const worksheet = XLSX.utils.json_to_sheet(dataExcel);
    const workbook = XLSX.utils.book_new();
    XLSX.utils.book_append_sheet(workbook, worksheet, "Data Guru");

    worksheet['!cols'] = [
        { wch: 5 },  
        { wch: 15 }, 
        { wch: 30 }, 
        { wch: 10 }, 
        { wch: 20 }, 
        { wch: 20 }, 
        { wch: 15 }  
    ];

    const namaFile = `Rekap_Data_Guru_${new Date().toLocaleDateString('id-ID').replace(/\//g, '-')}.xlsx`;
    XLSX.writeFile(workbook, namaFile);

    if (typeof catatAktivitasGuru === 'function') {
        catatAktivitasGuru("Mengexport data guru ke format Excel");
    }
}

function importExcelGuru(e) {
    const file = e.target.files[0];
    if (!file) return;

    if (typeof XLSX === 'undefined') {
        alert("Sistem gagal membaca Excel. Pastikan script SheetJS sudah terpasang di HTML!");
        e.target.value = "";
        return;
    }

    if (typeof verifikasiPasswordAdmin === 'function') {
        if (!verifikasiPasswordAdmin("mengimport data guru dari Excel")) {
            e.target.value = ""; 
            return;
        }
    }

    const reader = new FileReader();
    reader.onload = function (event) {
        try {
            const data = new Uint8Array(event.target.result);
            const workbook = XLSX.read(data, { type: 'array' });
            const sheetName = workbook.SheetNames[0];
            const rows = XLSX.utils.sheet_to_json(workbook.Sheets[sheetName]);

            let count = 0;
            rows.forEach(row => {
                let namaRaw = row["Nama Guru"] || row["Nama"] || row["nama"] || row["NAMA"];
                if (!namaRaw) return; 

                let noGuruRaw = row["No Guru / ID"] || row["No Guru"] || row["ID"] || ("G-" + Date.now().toString().slice(-4) + count);

                daftarGuru.push({
                    noGuru: noGuruRaw.toString().trim(),
                    nama: namaRaw.toString().trim(),
                    tahun: (row["Tahun"] || row["Tahun Masuk"] || "-").toString(),
                    daerah: (row["Daerah"] || row["Asal"] || "-").toString(),
                    bagian: (row["Bagian"] || row["Tugas"] || "-").toString(),
                    noHp: (row["No HP"] || row["NoHP"] || row["Telepon"] || "-").toString()
                });
                count++;
            });

            if (count > 0) {
                if (typeof simpanGuruKeStorage === 'function') simpanGuruKeStorage(); 
                if (typeof renderTabelGuru === 'function') renderTabelGuru(); 

                if (typeof catatAktivitasGuru === 'function') {
                    catatAktivitasGuru(`Mengimpor ${count} data guru dari file Excel`);
                }
                alert(`Berhasil mengimpor ${count} data guru!`);
            } else {
                alert("Tidak ada data yang berhasil diimpor. Pastikan format nama kolom Excel sudah benar.");
            }
            
            e.target.value = ""; 
        } catch (error) {
            console.error("Error membaca Excel:", error);
            alert("Gagal membaca file Excel. Pastikan menggunakan file format .xlsx yang valid.");
            e.target.value = "";
        }
    };
    reader.readAsArrayBuffer(file);
}

// ==================================================================
// FUNGSI NAVIGASI & RENDER TAB STATISTIK (GLOBAL SCOPE)
// ==================================================================

// Variabel penyimpan jenis ujian aktif pada Statistik Nilai
let jenisUjianStatistikAktif = 'Ulangan Umum';

// 1. Fungsi Buka Card Statistik
function bukaStatistikView(jenis) {
    const menuUtama = document.getElementById('statistik-menu-utama');
    const viewPembelajaran = document.getElementById('view-statistik-pembelajaran');
    const viewNilai = document.getElementById('view-statistik-nilai');

    // Sembunyikan semua dulu
    if (menuUtama) menuUtama.style.display = 'none';
    if (viewPembelajaran) viewPembelajaran.style.display = 'none';
    if (viewNilai) viewNilai.style.display = 'none';

    // Tampilkan view yang dipilih
    if (jenis === 'pembelajaran') {
        if (viewPembelajaran) viewPembelajaran.style.display = 'block';
        if (typeof isiDropdownFilterKelas === 'function') isiDropdownFilterKelas();
        if (typeof renderStatistikGlobal === 'function') renderStatistikGlobal();
    } else if (jenis === 'nilai') {
        if (viewNilai) viewNilai.style.display = 'block';
        if (typeof isiDropdownFilterKelas === 'function') isiDropdownFilterKelas();
        pilihStatistikUjian('Ulangan Umum'); // Otomatis muat data Ulangan Umum
    }
}

// 2. Fungsi Kembali ke Menu Card Statistik
function kembaliKeMenuStatistik() {
    const menuUtama = document.getElementById('statistik-menu-utama');
    const viewPembelajaran = document.getElementById('view-statistik-pembelajaran');
    const viewNilai = document.getElementById('view-statistik-nilai');

    if (menuUtama) menuUtama.style.display = 'block';
    if (viewPembelajaran) viewPembelajaran.style.display = 'none';
    if (viewNilai) viewNilai.style.display = 'none';
}

// 3. Fungsi Navigasi Sub-Tab (Jika ada tombol di dalam halaman)
function switchStatistikGlobalTab(tab) {
    const btnPembelajaran = document.getElementById('btn-stat-pembelajaran');
    const btnNilai = document.getElementById('btn-stat-nilai');
    const kontenPembelajaran = document.getElementById('konten-stat-pembelajaran') || document.querySelector('#statistik > .cards-container, #statistik > div:not(#konten-stat-nilai)');
    const kontenNilai = document.getElementById('konten-stat-nilai');

    if (tab === 'pembelajaran') {
        if (btnPembelajaran) { btnPembelajaran.style.background = '#b5532a'; btnPembelajaran.style.color = 'white'; }
        if (btnNilai) { btnNilai.style.background = '#ddd'; btnNilai.style.color = '#333'; }
        if (kontenPembelajaran) kontenPembelajaran.style.display = 'block';
        if (kontenNilai) kontenNilai.style.display = 'none';
    } else if (tab === 'nilai') {
        if (btnNilai) { btnNilai.style.background = '#b5532a'; btnNilai.style.color = 'white'; }
        if (btnPembelajaran) { btnPembelajaran.style.background = '#ddd'; btnPembelajaran.style.color = '#333'; }
        if (kontenPembelajaran) kontenPembelajaran.style.display = 'none';
        if (kontenNilai) kontenNilai.style.display = 'block';
        renderStatistikNilaiGlobal();
    }
}

// 4. Fungsi Pilih Jenis Ujian
function pilihStatistikUjian(jenisUjian) {
    jenisUjianStatistikAktif = jenisUjian;

    const btn1 = document.getElementById('btn-stat-ulangan-umum');
    const btn2 = document.getElementById('btn-stat-ujian-awal');
    const btn3 = document.getElementById('btn-stat-ujian-akhir');

    [btn1, btn2, btn3].forEach(b => {
        if (b) { b.style.background = '#ddd'; b.style.color = '#333'; }
    });

    if (jenisUjian === 'Ulangan Umum' && btn1) { btn1.style.background = '#b5532a'; btn1.style.color = 'white'; }
    if (jenisUjian === 'Ujian Awal Tahun' && btn2) { btn2.style.background = '#b5532a'; btn2.style.color = 'white'; }
    if (jenisUjian === 'Ujian Akhir Tahun' && btn3) { btn3.style.background = '#b5532a'; btn3.style.color = 'white'; }

    const judulEl = document.getElementById('judul-statistik-nilai-global');
    if (judulEl) judulEl.textContent = 'Statistik Nilai: ' + jenisUjian;

    renderStatistikNilaiGlobal();
}

// 5. Fungsi Render Tabel Nilai Global
function renderStatistikNilaiGlobal() {
    const filterKelasEl = document.getElementById('filter-kelas-statistik-nilai') || document.getElementById('filter-kelas-statistik');
    const kelasTerpilih = filterKelasEl ? filterKelasEl.value : "Semua";

    const siswaList = Object.values(databaseSiswa).filter(s => {
        return kelasTerpilih === "Semua" || s.kelas === kelasTerpilih;
    });

    let akupPel = {};
    if (typeof DAFTAR_PELAJARAN !== 'undefined') {
        DAFTAR_PELAJARAN.forEach(pel => { akupPel[pel] = { totalNilai: 0, count: 0 }; });
    }

    siswaList.forEach(siswa => {
        if (siswa.nilai && siswa.nilai[jenisUjianStatistikAktif]) {
            const mapNilai = siswa.nilai[jenisUjianStatistikAktif];
            Object.keys(mapNilai).forEach(pel => {
                const val = parseFloat(mapNilai[pel]);
                if (!isNaN(val) && akupPel[pel]) {
                    akupPel[pel].totalNilai += val;
                    akupPel[pel].count += 1;
                }
            });
        }
    });

    const wadahKeseluruhan = document.getElementById('tabel-nilai-keseluruhan-container');
    if (wadahKeseluruhan && typeof DAFTAR_PELAJARAN !== 'undefined') {
        let html = `
        <table style="width: 100%; border-collapse: collapse; font-size: 13px;">
            <thead>
                <tr style="background: #faf5ec; color: #b5532a;">
                    <th style="padding: 10px; border: 1px solid #eee; text-align: left;">Mata Pelajaran</th>
                    <th style="padding: 10px; border: 1px solid #eee; text-align: center;">Jumlah Data Nilai</th>
                    <th style="padding: 10px; border: 1px solid #eee; text-align: center;">Rata-rata Nilai (${jenisUjianStatistikAktif})</th>
                </tr>
            </thead>
            <tbody>
        `;

        let totalSemuaNilai = 0, totalSemuaCount = 0;

        DAFTAR_PELAJARAN.forEach(pel => {
            const data = akupPel[pel];
            const rata = data.count > 0 ? (data.totalNilai / data.count).toFixed(1) : '-';

            if (data.count > 0) {
                totalSemuaNilai += data.totalNilai;
                totalSemuaCount += data.count;
            }

            const warnaBg = typeof getWarnaNilai === 'function' ? getWarnaNilai(rata) : '#fff';
            const styleNilai = rata !== '-' ? `background-color: ${warnaBg}; font-weight: bold;` : '';

            html += `<tr>
            <td style="padding: 9px; border: 1px solid #eee; font-weight: bold; color: #3a2f2a;">${pel}</td>
            <td style="padding: 9px; border: 1px solid #eee; text-align: center;">${data.count} siswa</td>
            <td style="padding: 9px; border: 1px solid #eee; text-align: center; ${styleNilai}">${rata}</td>
            </tr>`;
        });

        const rataGlobal = totalSemuaCount > 0 ? (totalSemuaNilai / totalSemuaCount).toFixed(1) : '-';
        const warnaGlobal = typeof getWarnaNilai === 'function' ? getWarnaNilai(rataGlobal) : '#fff';

        html += `
            </tbody>
            <tfoot>
                <tr style="background: #faf5ec; font-weight: bold; border-top: 2px solid #b5532a; color: #b5532a;">
                    <td style="padding: 10px; border: 1px solid #eee; text-align: left;">RATA-RATA KESELURUHAN</td>
                    <td style="padding: 10px; border: 1px solid #eee; text-align: center;">-</td>
                    <td style="padding: 10px; border: 1px solid #eee; text-align: center; background-color: ${warnaGlobal};">${rataGlobal}</td>
                </tr>
            </tfoot>
        </table>
        `;
        wadahKeseluruhan.innerHTML = html;
    }

    const wadahPerKelas = document.getElementById('tabel-nilai-per-kelas-container');
    if (wadahPerKelas && typeof DAFTAR_PELAJARAN !== 'undefined') {
        let kelasSet = new Set();
        Object.values(databaseSiswa).forEach(s => { if (s.kelas) kelasSet.add(s.kelas); });
        let daftarKelas = Array.from(kelasSet).sort((a, b) => a.localeCompare(b, 'id', { numeric: true }));

        let htmlKelas = `
        <table style="width: 100%; border-collapse: collapse; font-size: 13px; overflow-x: auto; display: block;">
            <thead>
                <tr style="background: #faf5ec; color: #b5532a;">
                    <th style="padding: 10px; border: 1px solid #eee; text-align: left; min-width: 120px;">Kelas</th>
        `;
        DAFTAR_PELAJARAN.forEach(pel => { htmlKelas += `<th style="padding: 10px; border: 1px solid #eee; text-align: center; min-width: 90px;">${pel}</th>`; });
        htmlKelas += `</tr></thead><tbody>`;

        daftarKelas.forEach(kelas => {
            const siswaKelas = Object.values(databaseSiswa).filter(s => s.kelas === kelas);
            htmlKelas += `<tr><td style="padding: 9px; border: 1px solid #eee; font-weight: bold; color: #3a2f2a;">${kelas}</td>`;

            DAFTAR_PELAJARAN.forEach(pel => {
                let sum = 0, cnt = 0;
                siswaKelas.forEach(s => {
                    if (s.nilai && s.nilai[jenisUjianStatistikAktif] && s.nilai[jenisUjianStatistikAktif][pel] !== undefined) {
                        const v = parseFloat(s.nilai[jenisUjianStatistikAktif][pel]);
                        if (!isNaN(v)) { sum += v; cnt++; }
                    }
                });
                const avg = cnt > 0 ? (sum / cnt).toFixed(1) : '-';
                const warnaBg = typeof getWarnaNilai === 'function' ? getWarnaNilai(avg) : '#fff';
                const styleCell = avg !== '-' ? `background-color: ${warnaBg}; font-weight: 600; text-align: center;` : 'text-align: center; color: #777;';

                htmlKelas += `<td style="padding: 9px; border: 1px solid #eee; ${styleCell}">${avg}</td>`;
            });
            htmlKelas += `</tr>`;
        });

        htmlKelas += `</tbody></table>`;
        wadahPerKelas.innerHTML = htmlKelas;
    }
}

// 6. Fungsi Update Dropdown Kelas
function isiDropdownFilterKelas() {
    const ids = ['filter-kelas-statistik', 'filter-kelas-statistik-nilai'];
    let kelasSet = new Set();
    Object.values(databaseSiswa).forEach(s => { if (s.kelas) kelasSet.add(s.kelas); });
    let kelasArray = Array.from(kelasSet).sort((a, b) => a.localeCompare(b, 'id', { numeric: true }));

    ids.forEach(id => {
        const selectEl = document.getElementById(id);
        if (!selectEl) return;
        const kelasTerpilihSebelumnya = selectEl.value || "Semua";
        let optionsHtml = `<option value="Semua">Semua Kelas</option>`;
        
        kelasArray.forEach(kelas => {
            optionsHtml += `<option value="${kelas}">${kelas}</option>`; // Asumsi escapeHtml tidak selalu ada
        });

        selectEl.innerHTML = optionsHtml;
        selectEl.value = (kelasArray.includes(kelasTerpilihSebelumnya) || kelasTerpilihSebelumnya === "Semua") ? kelasTerpilihSebelumnya : "Semua";
    });
}

// 7. Fungsi Import Nilai Global
function importNilaiGlobalExcel() {
    let password = prompt("Masukkan password untuk import nilai global:");
    if (password !== "impervious") {
        if (password !== null) alert("Password salah!");
        return;
    }
    let jenisUjian = prompt("Masukkan jenis ujian (Contoh: Ulangan Umum / Ujian Awal Tahun):", "Ulangan Umum");
    if (!jenisUjian) return;
    if (typeof importNilaiSiswa === 'function') importNilaiSiswa(jenisUjian);
}

// ==================================================================
// FUNGSI POP-UP DETAIL AKTIVITAS GURU
// ==================================================================
function bukaDetailAktivitasGuru(namaGuru) {
    const modal = document.getElementById('modal-detail-aktivitas-guru');
    const judul = document.getElementById('judul-detail-aktivitas-guru');
    const list = document.getElementById('list-detail-aktivitas-guru');

    if (!modal || !judul || !list) return;

    judul.innerHTML = `<i class="fas fa-user-clock"></i> Aktivitas: ${namaGuru}`;

    let riwayat = JSON.parse(localStorage.getItem('riwayatAktivitasGuru')) || [];
    let tanggalHariIni = new Date().toLocaleDateString('id-ID');

    let aktivitasGuruIni = riwayat
        .filter(item => item.nama === namaGuru && item.tanggal === tanggalHariIni)
        .sort((a, b) => b.timestamp - a.timestamp); 

    list.innerHTML = "";
    if (aktivitasGuruIni.length === 0) {
        list.innerHTML = `<li style="padding: 15px; color: #777; font-style: italic; text-align: center;">Tidak ada aktivitas terekam.</li>`;
    } else {
        aktivitasGuruIni.forEach(item => {
            list.innerHTML += `
            <li style="padding: 12px 10px; border-bottom: 1px solid #f2e7da;">
                <div style="font-weight: bold; color: #b5532a; font-size: 13px; margin-bottom: 4px;">
                    <i class="far fa-clock"></i> Pukul ${item.waktu}
                </div>
                <div style="color: #3a2f2a; font-size: 14px;">
                    ${item.aktivitas}
                </div>
            </li>`;
        });
    }

    modal.style.display = 'flex';
}

function tutupDetailAktivitasGuru() {
    const modal = document.getElementById('modal-detail-aktivitas-guru');
    if (modal) modal.style.display = 'none';
}



/* ==================================================================
   [FITUR BARU] 3 DASHBOARD: Dashboard | Angkatan (D1) | Kelas (D2)
   Sumber data: recentActivityLog (siswa/kelas), riwayatAktivitasGuru (guru), daftarGuru.kelasWali (relasi wali-kelas)
   ================================================================== */
const DASH_PAGES = ['dashboard', 'dashboard-angkatan', 'dashboard-kelas'];
const _namaGuruAktif = () => sessionStorage.getItem('guruAktif') || '';
const _dataGuruAktif = () => daftarGuru.find(g => (g.nama || '').toLowerCase() === _namaGuruAktif().toLowerCase());
const isAdminAktif = () => { const g = _dataGuruAktif(); return _namaGuruAktif() === 'Admin Aplikasi' || !!(g && /admin/i.test(g.bagian || '')); };
const kelasWaliAktif = () => { const g = _dataGuruAktif(); return String((g && g.kelasWali) || '').split(/[,;]/).map(s => s.trim()).filter(Boolean); };
const _esc = t => escapeHtml(t);
const _ucf = s => s.charAt(0).toUpperCase() + s.slice(1);

function dashMulai(p) {
    const n = new Date(), s = new Date(n.getFullYear(), n.getMonth(), n.getDate()).getTime();
    return p === 'hari' ? s : p === 'minggu' ? s - 6 * 864e5 : p === 'bulan' ? new Date(n.getFullYear(), n.getMonth(), 1).getTime() : 0;
}
// Aktivitas siswa unik (nis+program+pelajaran+bab+subbab dihitung sekali) pada periode & kelas tertentu
function dashLog(p, kelas) {
    const t0 = dashMulai(p), seen = new Set(), out = [];
    recentActivityLog.forEach(a => {
        if (!a || !a.timestamp || a.timestamp < t0) return;
        if (kelas && kelas !== 'Semua' && a.kelas !== kelas) return;
        const k = [a.nis, a.program, a.pelajaran, a.bab, a.subbab].join('|');
        if (seen.has(k)) return; seen.add(k); out.push(a);
    });
    return out;
}
function dashTabel(head, rows, kosong) {
    if (!rows.length) return `<p class="dash-empty"><i class="fas fa-inbox"></i> ${kosong}</p>`;
    return `<div class="table-container dash-tbl"><table><thead><tr>${head.map(h => `<th>${h}</th>`).join('')}</tr></thead><tbody>${rows.map(r => `<tr>${r.map(c => `<td>${c}</td>`).join('')}</tr>`).join('')}</tbody></table></div>`;
}
const _medali = i => ['🥇', '🥈', '🥉'][i] || (i + 1);
const _val = id => (document.getElementById(id) || {}).value || '';

function dashSetNav(id) {
    const on = DASH_PAGES.includes(id);
    document.getElementById('dash-nav').style.display = on ? 'flex' : 'none';
    document.getElementById('page-title').style.display = on ? 'none' : '';
    document.querySelectorAll('#dash-nav .dash-tab').forEach(b => b.classList.toggle('active', b.dataset.dash === id));
    if (on) {
        document.querySelectorAll('.nav-links a').forEach(a => a.classList.toggle('active', a.dataset.target === 'dashboard'));
    }
}
const _pindahAsli = pindahHalaman;
pindahHalaman = function (id) {
    _pindahAsli(id);
    dashSetNav(id);
    if (id === 'dashboard-angkatan') renderDashAngkatan();
    if (id === 'dashboard-kelas') renderDashKelas();
};
const _refreshAsli = refreshDashboardBaru;
refreshDashboardBaru = function () {
    _refreshAsli();
    if (typeof halamanAktif !== 'undefined') {
        if (halamanAktif === 'dashboard-angkatan') renderDashAngkatan(true);
        if (halamanAktif === 'dashboard-kelas') renderDashKelas();
    }
};

/* ---------- D1: DASHBOARD ANGKATAN ---------- */
function renderDashAngkatan(tanpaGuru) {
    const p = _val('d1-periode') || 'minggu', kf = _val('d1-kelas') || 'Semua', q = _val('d1-cari').toLowerCase();
    const sel = document.getElementById('d1-kelas'), daftar = getDaftarKelasUnik();
    if (sel && sel.options.length !== daftar.length + 1) {
        sel.innerHTML = '<option value="Semua">Semua Kelas</option>' + daftar.map(k => `<option value="${_esc(k)}">${_esc(k)}</option>`).join('');
        sel.value = daftar.includes(kf) ? kf : 'Semua';
    }
    const log = dashLog(p, kf), semua = Object.values(databaseSiswa);
    const K = {}, S = {};
    semua.forEach(s => { const k = s.kelas || '-'; if (kf === 'Semua' || k === kf) (K[k] = K[k] || { kelas: k, total: 0, aktif: new Set(), aksi: 0 }).total++; });
    log.forEach(a => {
        const k = K[a.kelas] = K[a.kelas] || { kelas: a.kelas, total: 0, aktif: new Set(), aksi: 0 };
        k.aktif.add(a.nis); k.aksi++;
        const s = S[a.nis] = S[a.nis] || { nama: a.nama, kelas: a.kelas, aksi: 0, kat: {} };
        s.aksi++; s.kat[a.program] = (s.kat[a.program] || 0) + 1;
    });
    const kelasRank = Object.values(K).filter(k => k.aksi > 0).sort((a, b) => b.aksi - a.aksi || b.aktif.size - a.aktif.size || a.kelas.localeCompare(b.kelas, 'id', { numeric: true }));
    document.getElementById('d1-kelas-isi').innerHTML = dashTabel(['#', 'Kelas', 'Siswa Aktif', 'Aktivitas', 'Skor Keaktifan'],
        kelasRank.map((k, i) => { const pct = k.total ? Math.round(k.aktif.size / k.total * 100) : 0;
            return [_medali(i), `<b>${_esc(k.kelas)}</b>`, `${k.aktif.size} / ${k.total}`, k.aksi, `<div class="dash-bar"><span style="width:${pct}%"></span></div><small>${pct}% siswa aktif</small>`]; }),
        'Belum ada aktivitas pada periode ini.');
    const siswaRank = Object.values(S).filter(s => !q || s.nama.toLowerCase().includes(q)).sort((a, b) => b.aksi - a.aksi || a.nama.localeCompare(b.nama, 'id')).slice(0, 20);
    document.getElementById('d1-siswa-isi').innerHTML = dashTabel(['#', 'Nama', 'Kelas', 'Aktivitas', 'Program'],
        siswaRank.map((s, i) => [_medali(i), `<b>${_esc(s.nama)}</b>`, _esc(s.kelas), s.aksi, Object.keys(s.kat).map(x => `<span class="dash-chip">${_esc(_ucf(x))} ${s.kat[x]}</span>`).join('')]),
        q ? 'Siswa tidak ditemukan.' : 'Belum ada aktivitas pada periode ini.');
    document.getElementById('d1-sum').innerHTML = [['Total Siswa', semua.filter(s => kf === 'Semua' || s.kelas === kf).length], ['Siswa Aktif', Object.keys(S).length], ['Total Aktivitas', log.length]]
        .map(x => `<div class="card dash-stat"><h4>${x[0]}</h4><p class="card-value">${x[1]}</p></div>`).join('');
    if (!tanpaGuru) renderDashGuru(p, q);
}
function renderDashGuru(p, q) {
    const box = document.getElementById('d1-guru-isi');
    if (typeof firebaseDb === 'undefined') { box.innerHTML = '<p class="dash-empty">Firebase tidak tersedia.</p>'; return; }
    box.innerHTML = '<p class="dash-empty"><i class="fas fa-spinner fa-spin"></i> Memuat data guru...</p>';
    firebaseDb.ref('riwayatAktivitasGuru').once('value').then(snap => {
        const t0 = dashMulai(p), G = {};
        Object.values(snap.val() || {}).forEach(a => {
            if (!a || !a.nama || (a.timestamp || 0) < t0) return;
            const g = G[a.nama] = G[a.nama] || { nama: a.nama, aksi: 0, setoran: 0 };
            g.aksi++; if (/^Menerima setoran/.test(a.aktivitas || '')) g.setoran++;
        });
        const rows = Object.values(G).filter(g => !q || g.nama.toLowerCase().includes(q)).sort((a, b) => b.aksi - a.aksi || b.setoran - a.setoran).slice(0, 20).map((g, i) => {
            const d = daftarGuru.find(x => x.nama === g.nama);
            return [_medali(i), `<b>${_esc(g.nama)}</b>`, g.aksi, g.setoran, _esc((d && d.kelasWali) || '-')];
        });
        box.innerHTML = dashTabel(['#', 'Nama Guru', 'Total Aktivitas', 'Setoran Diterima', 'Kelas Dibina'], rows, 'Belum ada aktivitas guru pada periode ini.');
    }).catch(() => { box.innerHTML = '<p class="dash-empty" style="color:#c0392b"><i class="fas fa-exclamation-triangle"></i> Gagal memuat data guru. Periksa koneksi.</p>'; });
}

/* ---------- D2: DASHBOARD KELAS (WALI KELAS) ---------- */
function renderDashKelas() {
    const isi = document.getElementById('d2-isi'), sel = document.getElementById('d2-kelas'), admin = isAdminAktif();
    const ada = getDaftarKelasUnik(), norm = s => String(s).trim().toLowerCase();
    const opsi = admin ? ada : kelasWaliAktif().map(k => ada.find(a => norm(a) === norm(k)) || k);
    if (!opsi.length) {
        sel.innerHTML = ''; document.getElementById('d2-sum').innerHTML = '';
        isi.innerHTML = '<p class="dash-empty"><i class="fas fa-user-lock"></i> Akun Anda belum ditetapkan sebagai wali kelas. Minta admin mengisi kolom "Kelas Wali" pada data Anda di menu Guru.</p>'; return;
    }
    const lama = sel.value;
    if (sel.options.length !== opsi.length || ![...sel.options].every((o, i) => o.value === opsi[i])) {
        sel.innerHTML = opsi.map(k => `<option value="${_esc(k)}">${_esc(k)}</option>`).join('');
        sel.value = opsi.includes(lama) ? lama : opsi[0];
    }
    const kelas = sel.value;
    if (!admin && !opsi.includes(kelas)) { isi.innerHTML = '<p class="dash-empty">Anda tidak berhak melihat kelas ini.</p>'; return; }
    const p = _val('d2-periode') || 'minggu', siswa = Object.values(databaseSiswa).filter(s => s.kelas === kelas), log = dashLog(p, kelas), S = {};
    log.forEach(a => { const s = S[a.nis] = S[a.nis] || { nama: a.nama, aksi: 0 }; s.aksi++; s[a.program] = (s[a.program] || 0) + 1; });
    document.getElementById('d2-sum').innerHTML = [['Jumlah Siswa', siswa.length], ['Siswa Aktif', Object.keys(S).length], ['Belum Aktif', Math.max(siswa.length - Object.keys(S).length, 0)], ['Total Aktivitas', log.length]]
        .map(x => `<div class="card dash-stat"><h4>${x[0]}</h4><p class="card-value">${x[1]}</p></div>`).join('');
    const rows = Object.entries(S).sort((a, b) => b[1].aksi - a[1].aksi || a[1].nama.localeCompare(b[1].nama, 'id'))
        .map(([nis, s], i) => [_medali(i), `<b>${_esc(s.nama)}</b><br><small>${_esc(nis)}</small>`, _esc(kelas), `<b>${s.aksi}</b>`, ...DAFTAR_KATEGORI.map(k => s[k] || 0)]);
    isi.innerHTML = dashTabel(['#', 'Nama Siswa', 'Kelas', 'Aktivitas', ...DAFTAR_KATEGORI.map(_ucf)], rows, 'Belum ada aktivitas siswa kelas ini pada periode ini.');
}

// Kolom "Kelas Wali" pada form guru
(function () {
    const sudah = document.getElementById('input-kelaswali-guru');
    if (!sudah) { const hp = document.getElementById('input-hp-guru'); if (hp) hp.insertAdjacentHTML('afterend', '<label style="font-weight:600;font-size:13px;color:#3a2f2a;">Kelas Wali (opsional, pisahkan koma):</label><input type="text" id="input-kelaswali-guru" placeholder="Cth: 6-A, 6-B" style="width:100%;margin-bottom:15px;padding:10px;box-sizing:border-box;border-radius:5px;border:1px solid #ccc;">'); }
    const nav = document.getElementById('dash-nav');
    if (nav) nav.addEventListener('click', e => { const b = e.target.closest('.dash-tab'); if (b) pindahHalaman(b.dataset.dash); });
    dashSetNav('dashboard');
})();

/* ==================================================================
   [FITUR BARU] TARGET JUMBO (Guru -> Target Siswa)
   Data: Firebase 'targetJumbo/{id}' (1 catatan atomik, penerima = daftar NIS).
   Progres: dihitung dari recentActivityLog (setoran Sub Bab yang sudah ada), unik per nis+program+pelajaran+bab+subbab.
   ================================================================== */
let jbData = {}, jbSiap = false, jbDetail = null, jbSaving = false;
const jbTulis = new Set();
const jbT = s => new Date(s + 'T00:00:00').getTime(), jbTE = s => jbT(s) + 864e5 - 1;
const jbHariIni = () => new Date(Date.now() - new Date().getTimezoneOffset() * 6e4).toISOString().slice(0, 10);
const jbFmt = s => s ? new Date(s + 'T00:00:00').toLocaleDateString('id-ID', { day: 'numeric', month: 'long', year: 'numeric' }) : '-';
const jbAngkatan = k => (String(k).match(/^\s*(\d+)/) || [])[1] || 'Lainnya';
function jbKelasBoleh() {
    const ada = getDaftarKelasUnik();
    if (isAdminAktif()) return ada;
    const n = s => String(s).trim().toLowerCase(), w = kelasWaliAktif();
    return ada.filter(k => w.some(x => n(x) === n(k)));
}
function jbHitung(t) {
    const boleh = jbKelasBoleh(), set = new Set(t.penerima || []), t0 = jbT(t.mulai), seen = new Set(), ts = {}, now = Date.now();
    recentActivityLog.forEach(a => {
        if (!a || !set.has(a.nis) || a.timestamp < t0) return;
        const k = [a.nis, a.program, a.pelajaran, a.bab, a.subbab].join('|');
        if (seen.has(k)) return; seen.add(k); (ts[a.nis] = ts[a.nis] || []).push(a.timestamp);
    });
    const r = { rows: [], Selesai: 0, 'Dalam Proses': 0, Terlambat: 0, 'Belum Dimulai': 0 };
    set.forEach(nis => {
        const s = databaseSiswa[nis]; if (!s || !boleh.includes(s.kelas)) return;
        const arr = (ts[nis] || []).sort((a, b) => a - b), n = arr.length;
        const tSel = (t.selesai && t.selesai[nis]) || (n >= t.jumlah ? arr[t.jumlah - 1] : null);
        let st = tSel ? 'Selesai' : now > jbTE(t.deadline) ? 'Terlambat' : n > 0 ? 'Dalam Proses' : 'Belum Dimulai';
        if (tSel && !(t.selesai && t.selesai[nis]) && t.status !== 'dibatalkan' && typeof firebaseDb !== 'undefined' && !jbTulis.has(t.id + nis)) {
            jbTulis.add(t.id + nis); firebaseDb.ref(`targetJumbo/${t.id}/selesai/${nis}`).set(tSel).catch(() => jbTulis.delete(t.id + nis));
        }
        r[st]++; r.rows.push({ nis, nama: s.nama, kelas: s.kelas, n: tSel ? t.jumlah : Math.min(n, t.jumlah), st, tSel });
    });
    return r;
}
const jbBadge = st => `<span class="jb-badge jb-${st.replace(/ /g, '')}">${st}</span>`;
const jbBar = p => `<div class="dash-bar"><span style="width:${p}%"></span></div>`;

function jbPasangUI() {
    const v = document.getElementById('view-target-siswa'); if (!v || document.getElementById('jb-panel')) return;
    const lama = document.createElement('div'); lama.id = 'target-lama';
    [...v.children].slice(1).forEach(k => lama.appendChild(k)); v.appendChild(lama);
    v.children[0].insertAdjacentHTML('afterend', '<div class="tabs-menu jb-tabs"><button type="button" class="tab-btn active" data-jb="lama">Berikan Target Baru (Level Bab)</button><button type="button" class="tab-btn" data-jb="jumbo">Target Jumbo</button></div>');
    v.insertAdjacentHTML('beforeend', `<div id="jb-panel" style="display:none">
      <div id="jb-form" class="card" style="margin-bottom:24px"><h4 style="color:#b5532a"><i class="fas fa-layer-group"></i> Target Jumbo</h4>
        <div class="jb-grid">
          <label>Nama Target<input id="jb-nama" type="text" placeholder="Cth: Target Hafalan Pekanan"></label>
          <label>Jumlah Target Sub Bab<input id="jb-jumlah" type="number" min="1" step="1" placeholder="Cth: 10"></label>
          <label>Tanggal Mulai<input id="jb-mulai" type="date"></label>
          <label>Batas Waktu<input id="jb-deadline" type="date"></label>
          <label style="grid-column:1/-1">Deskripsi / Catatan (opsional)<input id="jb-catatan" type="text"></label>
          <label>Angkatan<select id="jb-angkatan" onchange="jbPilihAngkatan()"></select></label>
        </div>
        <div id="jb-kelas" class="jb-kelas"></div>
        <p id="jb-ringkas" class="jb-ringkas"></p>
        <div style="display:flex;gap:10px;flex-wrap:wrap"><button type="button" id="jb-btn" class="btn-add" onclick="jbBuat()">Buat Target Jumbo</button><button type="button" class="btn-add" style="background:#999" onclick="jbReset()">Batalkan</button></div>
      </div><div id="jb-list"></div></div>`);
    v.querySelector('.jb-tabs').addEventListener('click', e => { const b = e.target.closest('[data-jb]'); if (b) jbTab(b.dataset.jb); });
    if (typeof firebaseDb !== 'undefined') firebaseDb.ref('targetJumbo').on('value', s => { jbData = s.val() || {}; jbSiap = true; jbRender(); }, () => { jbSiap = 'err'; jbRender(); });
}
function jbTab(t) {
    document.querySelectorAll('.jb-tabs .tab-btn').forEach(b => b.classList.toggle('active', b.dataset.jb === t));
    document.getElementById('target-lama').style.display = t === 'lama' ? '' : 'none';
    document.getElementById('jb-panel').style.display = t === 'jumbo' ? '' : 'none';
    if (t === 'jumbo') { jbReset(); jbRender(); }
}
function jbReset() {
    ['jb-nama', 'jb-jumlah', 'jb-catatan', 'jb-deadline'].forEach(i => document.getElementById(i).value = '');
    document.getElementById('jb-mulai').value = jbHariIni();
    const boleh = jbKelasBoleh(), a = [...new Set(boleh.map(jbAngkatan))].sort((x, y) => x.localeCompare(y, 'id', { numeric: true }));
    document.getElementById('jb-angkatan').innerHTML = a.map(x => `<option value="${_esc(x)}">Angkatan ${_esc(x)}</option>`).join('');
    jbPilihAngkatan();
}
function jbPilihAngkatan() {
    const ang = _val('jb-angkatan'), boleh = jbKelasBoleh().filter(k => jbAngkatan(k) === ang), box = document.getElementById('jb-kelas');
    if (!boleh.length) { box.innerHTML = '<p class="dash-empty">Tidak ada kelas yang boleh Anda beri target. (Admin dapat mengisi "Kelas Wali" pada data guru.)</p>'; jbRingkas(); return; }
    box.innerHTML = `<label class="jb-cb-all"><input type="checkbox" id="jb-semua" onchange="document.querySelectorAll('.jb-cb').forEach(c=>c.checked=this.checked);jbRingkas()"> Semua Kelas dalam Angkatan</label>` +
        boleh.map(k => `<label class="jb-cb-k"><input type="checkbox" class="jb-cb" value="${_esc(k)}" onchange="jbRingkas()"> ${_esc(k)}</label>`).join('') +
        `<button type="button" class="btn-detail" onclick="document.querySelectorAll('.jb-cb,#jb-semua').forEach(c=>c.checked=false);jbRingkas()">Batalkan pilihan</button>`;
    jbRingkas();
}
function jbPilih() {
    const kelas = [...document.querySelectorAll('.jb-cb:checked')].map(c => c.value);
    return { kelas, siswa: Object.values(databaseSiswa).filter(s => kelas.includes(s.kelas)).map(s => s.nis) };
}
function jbRingkas() { const p = jbPilih(); document.getElementById('jb-ringkas').textContent = `Dipilih: ${p.kelas.length} kelas • ${p.siswa.length} siswa akan menerima target`; }
function jbBuat() {
    if (jbSaving) return;
    const nama = _val('jb-nama').trim(), jumlah = Number(_val('jb-jumlah')), mulai = _val('jb-mulai'), deadline = _val('jb-deadline'), p = jbPilih();
    if (!nama) return alert('Nama Target wajib diisi!');
    if (!Number.isInteger(jumlah) || jumlah < 1) return alert('Jumlah Target Sub Bab harus bilangan bulat positif!');
    if (!mulai || !deadline) return alert('Tanggal Mulai dan Batas Waktu wajib diisi!');
    if (deadline < mulai) return alert('Batas Waktu tidak boleh lebih awal dari Tanggal Mulai!');
    if (!p.kelas.length) return alert('Pilih minimal satu kelas!');
    if (!p.siswa.length) return alert('Tidak ada siswa pada kelas yang dipilih!');
    if (Object.values(jbData).some(t => t.status !== 'dibatalkan' && t.nama.toLowerCase() === nama.toLowerCase() && t.deadline === deadline && p.kelas.some(k => (t.kelas || []).includes(k)))) return alert('Target serupa (nama & batas waktu sama untuk kelas ini) sudah ada.');
    if (typeof firebaseDb === 'undefined') return alert('Firebase tidak tersedia. Target tidak dapat disimpan.');
    if (!confirm(`Konfirmasi Target Jumbo\n\nNama: ${nama}\nAngkatan: ${_val('jb-angkatan')}\nKelas: ${p.kelas.join(', ')}\nPenerima: ${p.siswa.length} siswa\nTarget: ${jumlah} Sub Bab per siswa\nMulai: ${jbFmt(mulai)}\nBatas waktu: ${jbFmt(deadline)}\n\nLanjutkan?`)) return;
    jbSaving = true; const btn = document.getElementById('jb-btn'); btn.disabled = true; btn.textContent = 'Menyimpan...';
    const id = 'j' + Date.now(), obj = { id, nama, catatan: _val('jb-catatan').trim(), jumlah, mulai, deadline, angkatan: _val('jb-angkatan'), kelas: p.kelas, penerima: p.siswa, status: 'aktif', dibuatOleh: _namaGuruAktif() || localStorage.getItem('guruAktif') || '-', dibuatPada: Date.now() };
    firebaseDb.ref('targetJumbo/' + id).set(obj).then(() => {
        alert(`Target Jumbo berhasil dibuat untuk ${p.kelas.length} kelas dan ${p.siswa.length} siswa.`);
        if (typeof catatAktivitasGuru === 'function') catatAktivitasGuru(`Membuat Target Jumbo "${nama}" untuk ${p.siswa.length} siswa`);
        jbReset();
    }).catch(() => alert('Gagal menyimpan Target Jumbo. Tidak ada data yang tersimpan, silakan coba lagi.'))
      .finally(() => { jbSaving = false; btn.disabled = false; btn.textContent = 'Buat Target Jumbo'; });
}
function jbRender() {
    const box = document.getElementById('jb-list'); if (!box || document.getElementById('jb-panel').style.display === 'none') return;
    document.getElementById('jb-form').style.display = jbDetail ? 'none' : '';
    if (jbSiap === 'err') { box.innerHTML = '<p class="dash-empty" style="color:#c0392b">Gagal memuat Target Jumbo. Periksa koneksi.</p>'; return; }
    if (!jbSiap) { box.innerHTML = '<p class="dash-empty"><i class="fas fa-spinner fa-spin"></i> Memuat...</p>'; return; }
    if (jbDetail && jbData[jbDetail]) return jbRenderDetail();
    jbDetail = null; document.getElementById('jb-form').style.display = '';
    const list = Object.values(jbData).sort((a, b) => b.dibuatPada - a.dibuatPada).map(t => ({ t, h: jbHitung(t) })).filter(x => x.h.rows.length);
    if (!list.length) { box.innerHTML = '<p class="dash-empty"><i class="fas fa-inbox"></i> Belum ada Target Jumbo.</p>'; return; }
    box.innerHTML = '<div class="jb-cards">' + list.map(({ t, h }) => {
        const tot = h.rows.length, pct = tot ? Math.round(h.Selesai / tot * 100) : 0, bt = t.status === 'dibatalkan';
        return `<div class="card jb-card"><h4 style="text-transform:none;letter-spacing:0;font-size:16px;color:#2f2723">${_esc(t.nama)} ${bt ? jbBadge('Dibatalkan') : ''}</h4>
        <small>${t.catatan ? _esc(t.catatan) + '<br>' : ''}Angkatan ${_esc(t.angkatan)} • Kelas: ${_esc((t.kelas || []).join(', '))}<br>${tot} siswa • ${t.jumlah} Sub Bab/siswa • ${jbFmt(t.mulai)} s.d. ${jbFmt(t.deadline)}</small>
        <div class="jb-stat"><span>Selesai <b>${h.Selesai}</b></span><span>Proses <b>${h['Dalam Proses']}</b></span><span>Belum <b>${h['Belum Dimulai']}</b></span><span>Terlambat <b>${h.Terlambat}</b></span></div>
        ${jbBar(pct)}<small>${pct}% selesai</small>
        <div style="margin-top:10px;display:flex;gap:8px"><button type="button" class="btn-detail" onclick="jbDetail='${t.id}';jbRender()">Detail</button>${bt ? '' : `<button type="button" class="btn-detail" style="color:#c0392b" onclick="jbBatalTarget('${t.id}')">Batalkan Target</button>`}</div></div>`;
    }).join('') + '</div>';
}
function jbBatalTarget(id) {
    if (!confirm('Batalkan target ini? Riwayat setoran siswa tidak dihapus, tetapi target ditandai dibatalkan.')) return;
    if (!verifikasiPasswordAdmin('membatalkan Target Jumbo')) return;
    firebaseDb.ref('targetJumbo/' + id).update({ status: 'dibatalkan', dibatalkanOleh: _namaGuruAktif() || '-', dibatalkanPada: Date.now() }).catch(() => alert('Gagal membatalkan target.'));
}
function jbRenderDetail() {
    const t = jbData[jbDetail], h = jbHitung(t), kl = [...new Set(h.rows.map(r => r.kelas))].sort((a, b) => a.localeCompare(b, 'id', { numeric: true }));
    document.getElementById('jb-list').innerHTML = `<button type="button" class="btn-back" onclick="jbDetail=null;jbRender()">← Kembali ke Daftar Target Jumbo</button>
      <div class="card"><h4 style="text-transform:none;letter-spacing:0;font-size:17px;color:#2f2723">${_esc(t.nama)}</h4><small>${t.jumlah} Sub Bab/siswa • ${jbFmt(t.mulai)} s.d. ${jbFmt(t.deadline)} • Dibuat oleh ${_esc(t.dibuatOleh)}</small>
      <div class="dash-filters" style="margin:14px 0"><input id="jbd-cari" class="dash-sel" placeholder="Cari nama siswa..." oninput="jbDetailTabel()">
        <select id="jbd-kelas" class="dash-sel" onchange="jbDetailTabel()"><option value="">Semua Kelas</option>${kl.map(k => `<option>${_esc(k)}</option>`).join('')}</select>
        <select id="jbd-status" class="dash-sel" onchange="jbDetailTabel()"><option value="">Semua Status</option><option>Selesai</option><option>Dalam Proses</option><option>Belum Dimulai</option><option>Terlambat</option></select>
        <select id="jbd-urut" class="dash-sel" onchange="jbDetailTabel()"><option value="nama">Urut Nama</option><option value="progres">Urut Progres</option><option value="status">Urut Status</option></select></div>
      <div id="jbd-tabel"></div></div>`;
    jbDetailTabel();
}
function jbDetailTabel() {
    const t = jbData[jbDetail], el = document.getElementById('jbd-tabel'); if (!t || !el) return;
    const q = _val('jbd-cari').toLowerCase(), k = _val('jbd-kelas'), s = _val('jbd-status'), u = _val('jbd-urut'), o = ['Terlambat', 'Belum Dimulai', 'Dalam Proses', 'Selesai'];
    const rows = jbHitung(t).rows.filter(r => (!q || r.nama.toLowerCase().includes(q)) && (!k || r.kelas === k) && (!s || r.st === s))
        .sort((a, b) => u === 'progres' ? b.n - a.n : u === 'status' ? o.indexOf(a.st) - o.indexOf(b.st) : a.nama.localeCompare(b.nama, 'id'));
    el.innerHTML = dashTabel(['Nama', 'Kelas', 'Progres', '', 'Status', 'Selesai Pada'], rows.map(r => [`<b>${_esc(r.nama)}</b>`, _esc(r.kelas), `${r.n}/${t.jumlah} Sub Bab`, jbBar(Math.round(r.n / t.jumlah * 100)), jbBadge(r.st), r.tSel ? new Date(r.tSel).toLocaleDateString('id-ID') : '-']), 'Tidak ada siswa yang cocok.');
}
const _refreshJb = refreshDashboardBaru;
refreshDashboardBaru = function () { _refreshJb(); if (jbSiap === true) { jbRender(); if (jbDetail) jbDetailTabel(); } };
jbPasangUI();
